from fastapi import FastAPI, Depends, Security
from fastapi.security import SecurityScopes, OAuth2PasswordBearer
from fastapi.testclient import TestClient

app = FastAPI()
oauth2_scheme = OAuth2PasswordBearer(tokenUrl="token")

def dep_d(security_scopes: SecurityScopes):
    return security_scopes.scopes

def dep_c(dep_d_res=Security(dep_d, scopes=["scope_c"])):
    return dep_d_res

def dep_b(dep_c_res=Security(dep_c, scopes=["scope_b"])):
    return dep_c_res

@app.get("/test")
def read_test(res=Security(dep_b, scopes=["scope_a"])):
    return res

app.dependency_overrides[oauth2_scheme] = lambda: "dummy-token"
client = TestClient(app)
print(f"Result: {client.get('/test', headers={'Authorization': 'Bearer dummy-token'}).json()}")
PY
"}

